import javax.net.ssl.X509TrustManager","edit_kind":"declaration","corrected_code":"import java.security.GeneralSecurityException
import java.security.KeyStore
import javax.net.ssl.SSLContext
import javax.net.ssl.SSLSocketFactory
import javax.net.ssl.TrustManagerFactory","reason":"Remove imports for the eliminated application-defined trust-manager parameter and import the platform trust-manager factory and KeyStore type used to initialize it.","symbol":"imports"},{"source_file_path":"data/src/main/java/org/cryptomator/data/cloud/webdav/network/SSLSocketFactories.kt","original_code":"	fun from(trustManager: X509TrustManager): SSLSocketFactory {
		return try {
			val tlsVersion = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
				"TLSv1.3"
			} else {
				"TLSv1.2"
			}
			val sslContext = SSLContext.getInstance(tlsVersion)
			sslContext.init(null, arrayOf<TrustManager>(trustManager), null)
			sslContext.socketFactory
		} catch (e: GeneralSecurityException) {
			throw FatalBackendException(e)
		}
	}","edit_kind":"method","corrected_code":"	fun from(): SSLSocketFactory {
		return try {
			val tlsVersion = if (android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.Q) {
				"TLSv1.3"
			} else {
				"TLSv1.2"
			}
			val trustManagerFactory = TrustManagerFactory.getInstance(TrustManagerFactory.getDefaultAlgorithm())
			trustManagerFactory.init(null as KeyStore?)
			val sslContext = SSLContext.getInstance(tlsVersion)
			sslContext.init(null, trustManagerFactory.trustManagers, null)
			sslContext.socketFactory
		} catch (e: GeneralSecurityException) {
			throw FatalBackendException(e)
		}
	}","reason":"Remove the application-defined TrustManager parameter and initialize SSLContext with the default TrustManagerFactory's trustManagers, while retaining the existing TLS version selection and null KeyManager[] and SecureRandom arguments.","symbol":"SSLSocketFactories.from"}],"manual_review_required":true,"provided_contracts":["SSLSocketFactories.from is now an internal no-argument function returning an SSLSocketFactory backed by TrustManagerFactory default trust managers."],"required_contracts":["WebDavCompatibleHttpClient.kt must replace SSLSocketFactories.from(trustManager) with SSLSocketFactories.from()."],"source_file_path":"data/src/main/java/org/cryptomator/data/cloud/webdav/network/SSLSocketFactories.kt","required_tests":[]}
